// Environment variable value, empty when unset.
inline std::string tour_env(const char* name) {
#ifdef _MSC_VER
    char* value = nullptr;
    std::size_t size = 0;
    if (_dupenv_s(&value, &size, name) != 0 || !value) return {};
    std::string result(value);
    std::free(value);
    return result;
#else
    const char* value = std::getenv(name);
    return value ? std::string(value) : std::string();
#endif
}

// Directory of this executable (extensions and the assets/ folder are deployed next to it).
inline std::string tour_executable_dir() {
    std::string result;
#ifdef _WIN32
    char* program = nullptr;
    if (_get_pgmptr(&program) != 0 || !program) return ".";
    result = program;
#elif defined(__APPLE__)
    char path[4096] = {};
    uint32_t length = sizeof path;
    if (_NSGetExecutablePath(path, &length) != 0) return ".";
    result = path;
#else
    char path[4096] = {};
    const ssize_t length = readlink("/proc/self/exe", path, sizeof path - 1);
    if (length <= 0) return ".";
    path[length] = '\0';
    result = path;
#endif
    const auto slash = result.find_last_of("/\\");
    return slash == std::string::npos ? std::string(".") : result.substr(0, slash);
}

