// ---- host logic: examples/api_tours/platform/host.cpp ----
// API tour (C++ Wrapper): platform services. Same page, checks and case as
// examples/c/ports/kui_api_platform.c (and the Go / Rust ports): the host reads the monotonic clock,
// runs timeouts / intervals / idle callbacks / posted tasks, pumps the event loop by hand
// (Platform::pollEvents / waitEvents), round-trips the clipboard (putting the original text back),
// queries the monitors and toggles F12 DevTools. One #tour-log row per check; #tour-result ends as
// "PASS n/n" once the timers have fired. Message box, file dialogs and openUrl are only behind
// (grey) buttons: they are modal or open the system browser.
//
// Wrapper shapes that differ from the C port (checked through the closest public method):
//   * A failing call throws kui::Error; its status() is the C status.
//   * Platform::postToMainThread returns nothing (a refused post is dropped); the task itself is
//     checked.
//   * Platform::clipboardText() and Platform::monitors() size their buffers / indexes themselves, so
//     the C port's small-buffer (clip.get_clipboard_text-buffer-too-small) and out-of-range index
//     (mon.get_monitor-out-of-range) checks have no Wrapper form and are left out.

#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <functional>
#include <sstream>
#include <vector>

namespace {

kui::Document* g_doc = nullptr;
kui::Window* g_window = nullptr;

// ---- Self-check bookkeeping: count, log one <tr> per check, publish the verdict ----------
// check():  a documented behaviour; a failure makes the tour FAIL.
// skip():   not possible in this environment; logged, not counted.

int g_total = 0;
int g_failed = 0;
std::string g_failed_names;

template <typename... Parts>
std::string cat(const Parts&... parts) {
    std::ostringstream out;
    out.setf(std::ios::fixed);
    out.precision(1);
    (out << ... << parts);
    return out.str();
}

std::string fixed(double value, int digits) {
    char buf[48];
    std::snprintf(buf, sizeof buf, "%.*f", digits, value);
    return buf;
}

void log_row(const std::string& name, const std::string& result, const std::string& cell) {
    kui::Element* log = g_doc->getElementById("tour-log");
    if (!log) return;
    auto row = g_doc->createElement("tr");
    row->setAttribute("data-check", name);
    row->setAttribute("data-result", result);
    if (result == "fail") row->addClass("bad");
    auto first = g_doc->createElement("td");
    first->setTextContent(name);
    row->appendChild(first);
    auto second = g_doc->createElement("td");
    second->setTextContent(cell);
    row->appendChild(second);
    log->appendChild(row);
}

void check(const std::string& name, bool ok, const std::string& detail) {
    g_total++;
    if (ok) {
        log_row(name, "ok", "ok");
        return;
    }
    g_failed++;
    g_failed_names += (g_failed_names.empty() ? "" : ", ") + name;
    std::fprintf(stderr, "tour check failed: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "fail", "FAIL: " + detail);
}

void skip(const std::string& name, const std::string& why) { log_row(name, "skip", "skipped: " + why); }

void finish() {
    kui::Element* result = g_doc->getElementById("tour-result");
    if (!result) return;
    const std::string text = g_failed == 0 ? cat("PASS ", g_total, "/", g_total)
                                           : cat("FAIL ", g_failed, "/", g_total, ": ", g_failed_names);
    result->setTextContent(text);
    result->setAttribute("data-total", std::to_string(g_total));
    result->setAttribute("data-failed", std::to_string(g_failed));
    result->setAttribute("data-known", "0");
    result->addClass(g_failed == 0 ? "pass" : "fail");
}

// A Wrapper method that throws (kui::Error) fails its group instead of aborting the tour.
void run_group(const char* group, const std::function<void()>& body) {
    try {
        body();
    } catch (const std::exception& error) {
        check(cat(group, ".exception"), false, error.what());
    }
}

// The status a Wrapper call reports: KUI_OK, or the kui::Error it throws.
template <typename Fn>
KuiStatus status_of(Fn&& fn) {
    try {
        fn();
        return KUI_OK;
    } catch (const kui::Error& error) {
        return error.status();
    }
}

int st(KuiStatus status) { return static_cast<int>(status); }

void set_text(const char* id, const std::string& text) {
    if (kui::Element* element = g_doc->getElementById(id)) element->setTextContent(text);
}

double now_ms() { return kui::Platform::now(); }

// ---- Clock, timers, idle callbacks, posted tasks ------------------------------------------

double g_timeout_started = 0.0;
double g_timeout_elapsed = -1.0;
int g_interval_ticks = 0;
kui::u32 g_interval_id = 0;
int g_cancelled_fired = 0;
int g_idle_ran = 0;
int g_posted_ran = 0;

void check_clock_and_timers() {
    double first = 0.0;
    const KuiStatus status = status_of([&] { first = kui::Platform::now(); });
    const double second = now_ms();
    // The runtime version of the loaded library (Platform::runtimeVersion) goes into the detail text.
    const KuiVersion runtime = kui::Platform::runtimeVersion();
    check("time.now", status == KUI_OK && first > 0.0 && second >= first,
          cat("status ", st(status), " now ", fixed(first, 3), " then ", fixed(second, 3), " (KUI ", runtime.major, ".",
              runtime.minor, ".", runtime.patch, ")"));

    g_timeout_started = now_ms();
    const kui::u32 timer = kui::Platform::setTimeout([] { g_timeout_elapsed = now_ms() - g_timeout_started; }, 50);
    check("time.set_timeout", timer != 0, cat("id ", timer));
    // Clears itself on the third tick.
    g_interval_id = kui::Platform::setInterval([] {
        if (++g_interval_ticks == 3) kui::Platform::clearTimer(g_interval_id);
    }, 30);
    check("time.set_interval", g_interval_id != 0 && g_interval_id != timer, cat("id ", g_interval_id));
    const kui::u32 cancelled = kui::Platform::setTimeout([] { g_cancelled_fired++; }, 40);
    const KuiStatus cleared = status_of([&] { kui::Platform::clearTimer(cancelled); });
    check("time.clear_timer", cleared == KUI_OK, cat("status ", st(cleared)));
    const KuiStatus idle = status_of([&] { kui::Platform::requestIdle([] { g_idle_ran++; }); });
    check("time.request_idle", idle == KUI_OK, cat("status ", st(idle)));
}

// ---- Pumping the loop by hand: a posted task runs inside pollEvents / waitEvents -----------

void check_event_loop() {
    kui::Platform::postToMainThread([] { g_posted_ran++; });
    check("loop.post_to_main_thread-async", g_posted_ran == 0,
          cat("ran ", g_posted_ran, " time(s) before the loop"));
    KuiStatus status = status_of([] { kui::Platform::pollEvents(); });
    check("loop.poll_events-runs-posted-task", status == KUI_OK && g_posted_ran == 1,
          cat("status ", st(status), ", posted task ran ", g_posted_ran, " time(s)"));

    double started = now_ms();
    status = status_of([] { kui::Platform::waitEvents(0.05); });
    double elapsed = now_ms() - started;
    check("loop.wait_events-timeout", status == KUI_OK && elapsed < 1000.0,
          cat("status ", st(status), " returned after ", elapsed, " ms"));
    // A posted task wakes a waiting loop at once.
    const int before = g_posted_ran;
    kui::Platform::postToMainThread([] { g_posted_ran++; });
    started = now_ms();
    status = status_of([] { kui::Platform::waitEvents(2.0); });
    elapsed = now_ms() - started;
    if (g_posted_ran == before) kui::Platform::pollEvents();
    check("loop.wait_events-woken-by-post", status == KUI_OK && g_posted_ran == before + 1 && elapsed < 1500.0,
          cat("status ", st(status), ", ran ", before, " -> ", g_posted_ran, ", waited ", elapsed, " ms of 2000"));
}

// ---- Clipboard round trip (original text restored) -----------------------------------------

const char* const k_sample = "KUI clipboard \xe4\xbd\xa0\xe5\xa5\xbd 42";

// Saves, writes the sample, reads it back, restores. Returns the summary line; *outcome is
// 1 (round trip ok), 0 (failed) or -1 (the clipboard holds no text and was left alone).
std::string clipboard_round_trip(bool self_check, int* outcome) {
    if (!kui::Platform::hasClipboardText()) {
        *outcome = -1;
        return "clipboard holds no text: left alone";
    }
    std::string original;
    if (status_of([&] { original = kui::Platform::clipboardText(); }) != KUI_OK) {
        *outcome = 0;
        return "could not read the clipboard";
    }
    const KuiStatus status = status_of([] { kui::Platform::setClipboardText(k_sample); });
    const bool has_after = kui::Platform::hasClipboardText();
    std::string read_back;
    const bool read_ok = status_of([&] { read_back = kui::Platform::clipboardText(); }) == KUI_OK;
    const bool ok = status == KUI_OK && has_after && read_ok && read_back == k_sample;
    if (self_check) {
        check("clip.set_clipboard_text", status == KUI_OK && has_after,
              cat("status ", st(status), " has ", has_after ? 1 : 0));
        check("clip.get_clipboard_text", read_ok && read_back == k_sample,
              cat("read back '", read_ok ? read_back : std::string("(null)"), "'"));
    }
    kui::Platform::setClipboardText(original);
    std::string restored;
    const bool restored_ok = status_of([&] { restored = kui::Platform::clipboardText(); }) == KUI_OK &&
                             restored == original;
    if (self_check) {
        check("clip.restored", restored_ok,
              cat("original of ", original.size(), " bytes, now ", restored.size(), " bytes"));
    }
    *outcome = ok ? 1 : 0;
    return cat("round trip ", ok ? "ok" : "FAILED", " (sample of ", std::string(k_sample).size(),
               " bytes), original text (", original.size(), " bytes) restored=", restored_ok ? 1 : 0);
}

void check_clipboard() {
    bool has = false;
    const KuiStatus status = status_of([&] { has = kui::Platform::hasClipboardText(); });
    check("clip.has_clipboard_text", status == KUI_OK, cat("status ", st(status), " has ", has ? 1 : 0));
    int outcome = 0;
    clipboard_round_trip(true, &outcome);
    if (outcome < 0) skip("clip.round-trip", "the clipboard holds no text now; it is not overwritten");
}

// ---- Monitors ---------------------------------------------------------------------------------

using Monitor = kui::Platform::MonitorInfo;

bool same_rect(const Monitor& a, const Monitor& b) {
    return a.bounds.x == b.bounds.x && a.bounds.y == b.bounds.y && a.bounds.width == b.bounds.width &&
           a.bounds.height == b.bounds.height;
}

bool contains(const Monitor& m, float x, float y) {
    return x >= m.bounds.x && y >= m.bounds.y && x < m.bounds.x + m.bounds.width && y < m.bounds.y + m.bounds.height;
}

std::string describe(const Monitor& m) {
    return cat(m.name, m.name.empty() ? "" : ": ", fixed(m.bounds.width, 0), "x", fixed(m.bounds.height, 0), " at (",
               fixed(m.bounds.x, 0), ", ", fixed(m.bounds.y, 0), ") work ", fixed(m.workArea.width, 0), "x",
               fixed(m.workArea.height, 0), " scale ", fixed(m.scale, 2), m.isPrimary ? " primary" : "");
}

std::string bounds_text(const Monitor& m) {
    return cat(fixed(m.bounds.width, 0), "x", fixed(m.bounds.height, 0), " at (", fixed(m.bounds.x, 0), ", ",
               fixed(m.bounds.y, 0), ")");
}

// ---- Diagnostics: console, stack trace writer, crash reporter, input method -------------------

void check_diagnostics() {
    auto& console = kui::Console::instance();
    const KuiStatus console_status = status_of([&] {
        console.setEnabled(true);
        console.setStderrOutput(false);
        console.setMinLevel(kui::LogLevel::Debug);
    });
    check("diag.console_configure", console_status == KUI_OK, cat("status ", static_cast<int>(console_status)));

    bool stack_installed = false;
    const KuiStatus stack_status = status_of([&] {
        kui::StackTrace::Config config;
        config.outputMode = kui::StackTrace::WriteToStderr;
        stack_installed = kui::StackTrace::install(config);
        kui::StackTrace::uninstall();
    });
    check("diag.stack_trace_install_uninstall", stack_status == KUI_OK,
          cat("status ", static_cast<int>(stack_status), ", installed ", stack_installed));

    // Without crashpad_handler next to the executable the call succeeds and reports false.
    bool crash_installed = false;
    const KuiStatus crash_status = status_of([&] {
        crash_installed = kui::CrashReporter::install();
        kui::CrashReporter::uninstall();
    });
    check("diag.crash_reporter_install_uninstall", crash_status == KUI_OK,
          cat("status ", static_cast<int>(crash_status), ", installed ", crash_installed));

    // Windows turns the input method off for this thread; other platforms report NOT_SUPPORTED.
    const KuiStatus ime_status = status_of([] { kui::Platform::disableIme(); });
    check("diag.disable_ime", ime_status == KUI_OK || ime_status == KUI_ERR_NOT_SUPPORTED,
          cat("status ", static_cast<int>(ime_status)));
}

void check_monitors() {
    std::vector<Monitor> list;
    const KuiStatus status = status_of([&] { list = kui::Platform::monitors(); });
    check("mon.get_monitor_count", status == KUI_OK && !list.empty(),
          cat("status ", st(status), " count ", list.size()));
    int primaries = 0;
    bool valid = true;
    Monitor listed_primary;
    for (const Monitor& monitor : list) {
        if (monitor.bounds.width <= 0.0f || monitor.bounds.height <= 0.0f || monitor.workArea.width <= 0.0f ||
            monitor.workArea.width > monitor.bounds.width || monitor.scale <= 0.0f) {
            valid = false;
        }
        if (monitor.isPrimary) {
            primaries++;
            listed_primary = monitor;
        }
    }
    check("mon.get_monitor", valid && primaries == 1, cat("valid ", valid ? 1 : 0, ", ", primaries,
                                                           " primary monitor(s)"));

    Monitor primary;
    KuiStatus result = status_of([&] { primary = kui::Platform::primaryMonitor(); });
    check("mon.get_primary_monitor", result == KUI_OK && primary.isPrimary && same_rect(primary, listed_primary),
          cat("status ", st(result), " bounds ", bounds_text(primary)));

    const float cx = primary.bounds.x + primary.bounds.width * 0.5f;
    const float cy = primary.bounds.y + primary.bounds.height * 0.5f;
    Monitor from_point;
    result = status_of([&] { from_point = kui::Platform::monitorFromPoint(cx, cy); });
    check("mon.get_monitor_from_point", result == KUI_OK && same_rect(from_point, primary) && from_point.isPrimary,
          cat("status ", st(result), " bounds ", bounds_text(from_point)));

    const kui::Point position = g_window->position();
    const float wx = position.x + static_cast<float>(g_window->width()) * 0.5f;
    const float wy = position.y + static_cast<float>(g_window->height()) * 0.5f;
    Monitor from_window;
    result = status_of([&] { from_window = kui::Platform::monitorFromWindow(g_window->nativeHandle()); });
    check("mon.get_monitor_from_window", result == KUI_OK && contains(from_window, wx, wy),
          cat("status ", st(result), " window centre (", fixed(wx, 0), ", ", fixed(wy, 0), "), monitor ",
              bounds_text(from_window)));
    result = status_of([] { kui::Platform::monitorFromWindow(nullptr); });
    check("mon.get_monitor_from_window-null", result == KUI_ERR_INVALID_ARG, cat("status ", st(result)));
}

// ---- F12 DevTools switch (default off) ------------------------------------------------------

void check_f12() {
    const KuiStatus on = status_of([] { kui::Platform::setF12DevToolsEnabled(true); });
    const KuiStatus off = status_of([] { kui::Platform::setF12DevToolsEnabled(false); });
    check("shell.set_f12_devtools_enabled", on == KUI_OK && off == KUI_OK, cat("on ", st(on), " off ", st(off)));
}

// ---- Document::loadFile on a separate document (C++-only check) ---------------------------
// Never on the tour's own document (that would replace the page): a detached Document::create()
// loads a small HTML file written to the temp directory; the file is removed afterwards.

void check_load_file() {
    std::error_code ec;
    const std::filesystem::path file =
        std::filesystem::temp_directory_path(ec) / "kui_api_platform_load_file.html";
    {
        std::ofstream out(file, std::ios::binary | std::ios::trunc);
        out << "<!doctype html><html><body><p id=\"lf-probe\">loaded from file</p></body></html>";
    }
    const auto utf8 = file.u8string();
    const std::string path(utf8.begin(), utf8.end());
    std::string text = "<missing>";
    KuiStatus result = KUI_OK;
    try {
        kui::RefPtr<kui::Document> scratch = kui::Document::create();
        scratch->loadFile(path);
        if (kui::Element* probe = scratch->getElementById("lf-probe")) text = probe->textContent();
    } catch (const kui::Error& error) {
        result = error.status();
    }
    std::filesystem::remove(file, ec);
    check("doc.load_file", result == KUI_OK && text == "loaded from file",
          cat("status ", st(result), ", #lf-probe '", text, "'"));
}

// ---- Verdict once the timers have had their turn ----------------------------------------

void finalize() {
    check("time.set_timeout-fired", g_timeout_elapsed >= 45.0,
          cat("fired after ", g_timeout_elapsed, " ms (-1 = never)"));
    check("time.set_interval-ticks", g_interval_ticks == 3, cat(g_interval_ticks, " tick(s), cleared on the third"));
    check("time.clear_timer-cancelled", g_cancelled_fired == 0,
          cat("cleared timeout ran ", g_cancelled_fired, " time(s)"));
    check("time.request_idle-ran", g_idle_ran == 1, cat("idle callback ran ", g_idle_ran, " time(s)"));
    finish();
}

// ---- Panel buttons ------------------------------------------------------------------------

double g_button_started = 0.0;
int g_button_ticks = 0;
kui::u32 g_button_interval = 0;
int g_poll_ran = 0;

void on_timeout_btn() {
    g_button_started = now_ms();
    kui::Platform::setTimeout([] {
        set_text("time-out", cat("timeout fired after ", now_ms() - g_button_started >= 95.0 ? ">= " : "< ", "100 ms"));
    }, 100);
    set_text("time-out", "waiting 100 ms...");
}

void on_interval_btn() {
    g_button_ticks = 0;
    g_button_interval = kui::Platform::setInterval([] {
        if (++g_button_ticks == 3) kui::Platform::clearTimer(g_button_interval);
        set_text("time-out", cat("interval tick ", g_button_ticks, " of 3"));
    }, 50);
}

void on_cancel_btn() {
    const kui::u32 id = kui::Platform::setTimeout([] { set_text("time-out", "the cleared timer fired (bug)"); }, 30);
    const KuiStatus status = status_of([&] { kui::Platform::clearTimer(id); });
    set_text("time-out", cat("timer set and cleared: status ", st(status)));
}

void on_poll_btn() {
    const int before = g_poll_ran;
    kui::Platform::postToMainThread([] { g_poll_ran++; });
    kui::Platform::pollEvents();
    set_text("loop-out", cat("posted task ran inside poll_events: ", g_poll_ran == before + 1 ? "yes" : "no"));
}

void on_wait_btn() {
    const double started = now_ms();
    const KuiStatus status = status_of([] { kui::Platform::waitEvents(0.05); });
    set_text("loop-out", cat("wait_events(0.05): status ", st(status), ", returned within 1 s: ",
                             now_ms() - started < 1000.0 ? "yes" : "no"));
}

void on_clip_read() {
    const bool has = kui::Platform::hasClipboardText();
    std::string copy;
    if (has) status_of([&] { copy = kui::Platform::clipboardText(); });
    set_text("clip-out", cat("has text=", has ? 1 : 0, " (", copy.size(), " bytes)"));
}

void on_clip_trip() {
    int outcome = 0;
    set_text("clip-out", clipboard_round_trip(false, &outcome));
}

void on_mon_list() {
    const std::vector<Monitor> list = kui::Platform::monitors();
    std::string text = cat(list.size(), " monitor(s)");
    for (const Monitor& monitor : list) text += " | " + describe(monitor);
    set_text("mon-out", text);
}

void on_mon_window() {
    Monitor monitor;
    if (status_of([&] { monitor = kui::Platform::monitorFromWindow(g_window->nativeHandle()); }) != KUI_OK) {
        set_text("mon-out", "monitor lookup failed");
        return;
    }
    set_text("mon-out", "this window: " + describe(monitor));
}

// Manual: modal.
void on_msg() {
    const kui::Platform::MsgBoxResult result = kui::Platform::messageBox(
        "KUI API tour", "Do you like message boxes?", kui::Platform::MsgBoxType::Question,
        kui::Platform::MsgBoxButtons::YesNo);
    set_text("shell-out", cat("message box answer: ", result == kui::Platform::MsgBoxResult::Yes ? "yes" : "no"));
}

const std::vector<std::string> k_filters = {"HTML pages|*.html;*.htm", "All files|*.*"};

void show_path(const char* what, const kui::Optional<std::string>& path) {
    set_text("shell-out", path ? cat(what, ": status 0 ", *path) : cat(what, ": cancelled"));
}

// Manual: the three file dialogs are modal.
void on_open() {
    show_path("open", kui::Platform::openFileDialog(kui::Platform::FileDialogOptions("Open a page", "", k_filters)));
}

void on_save() {
    show_path("save", kui::Platform::saveFileDialog(
                          kui::Platform::FileDialogOptions("Save the page as", "tour.html", k_filters)));
}

void on_folder() { show_path("folder", kui::Platform::selectFolderDialog("Pick a folder")); }

// Manual: opens the system browser.
void on_url() {
    const KuiStatus status = status_of([] { kui::Platform::openUrl("https://example.com/"); });
    set_text("shell-out", cat("open_url: status ", st(status)));
}

// Clicks on #id run `handler` (a missing button is reported as a failed check).
void on_click(const char* id, std::function<void()> handler) {
    kui::Element* button = g_doc->getElementById(id);
    if (!button) {
        check(cat("ui.", id), false, "button missing");
        return;
    }
    button->addEventListener("click", [handler](kui::Event&) {
        try {
            handler();
        } catch (const std::exception& error) {
            std::fprintf(stderr, "kui_api_platform: %s\n", error.what());
        }
    });
}

}  // namespace

void tour_ready(kui::Window& window, kui::Document& document) {
    g_doc = &document;
    g_window = &window;

    run_group("time", check_clock_and_timers);
    run_group("loop", check_event_loop);
    run_group("clip", check_clipboard);
    run_group("mon", check_monitors);
    run_group("shell", check_f12);
    run_group("doc", check_load_file);
    run_group("diag", check_diagnostics);
    kui::Platform::setTimeout(finalize, 700);

    on_click("btn-timeout", on_timeout_btn);
    on_click("btn-interval", on_interval_btn);
    on_click("btn-cancel", on_cancel_btn);
    on_click("btn-idle", [] { kui::Platform::requestIdle([] { set_text("time-out", "idle callback ran"); }); });
    on_click("btn-post", [] {
        kui::Platform::postToMainThread([] { set_text("time-out", "posted task ran on the UI thread"); });
    });
    on_click("btn-poll", on_poll_btn);
    on_click("btn-wait", on_wait_btn);
    on_click("btn-clip-read", on_clip_read);
    on_click("btn-clip-trip", on_clip_trip);
    on_click("btn-mon-list", on_mon_list);
    on_click("btn-mon-window", on_mon_window);
    on_click("btn-msg", on_msg);
    on_click("btn-open", on_open);
    on_click("btn-save", on_save);
    on_click("btn-folder", on_folder);
    on_click("btn-url", on_url);
    on_click("btn-f12-on", [] {
        set_text("shell-out", status_of([] { kui::Platform::setF12DevToolsEnabled(true); }) == KUI_OK
                                  ? "F12 enabled: F12 opens DevTools in the browser"
                                  : "set_f12_devtools_enabled failed");
    });
    on_click("btn-f12-off", [] {
        set_text("shell-out", status_of([] { kui::Platform::setF12DevToolsEnabled(false); }) == KUI_OK
                                  ? "F12 disabled"
                                  : "set_f12_devtools_enabled failed");
    });
}
// ---- end of examples/api_tours/platform/host.cpp ----

int main() {
    try {
        if (!kui::Platform::init()) return 3;
        kui::WindowConfig config;
        config.title = "KUI API \xe2\x80\x94 Platform services";
        config.width = 1100;
        config.height = 780;
        auto window = kui::Window::create(config);
        if (!window) return 4;
        kui::Document* document = window->document();
        auto script = kui::ScriptEngine::create();
        if (script) {
            script->setErrorHandler([](const std::string& error, const std::string& source, int line) {
                std::fprintf(stderr, "[Lua] %s:%d: %s\n", source.c_str(), line, error.c_str());
            });
            script->bindDocument(document);
            window->setScriptEngine(script.get());
        }
        tour_script = script.get();
        document->loadHTML(k_tour_page);
        if (script) script->executeScripts();
        // Test hook shared with the C / Go / Rust runners: KUI_EXAMPLE_DEVTOOLS_PORT=<port> starts
        // DevTools so scripts/verify_example_ports.py can click and read the DOM.
        const std::string port = tour_env("KUI_EXAMPLE_DEVTOOLS_PORT");
        if (!port.empty()) window->startDevTools(static_cast<kui::u16>(std::atoi(port.c_str())));
        tour_ready(*window, *document);
        const int code = kui::Platform::run();
        tour_script = nullptr;
        return code;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "[kui_api_platform] %s\n", error.what());
        return 9;
    }
}
